/// The kinds of panel, and what differs between them (plan 0062 D14).
enum VrxDisplayClass {
  lcdColour,
  lcdGrey,
  epaperGrey,
  epaperMono,
}

class VrxClassRow {
  const VrxClassRow({required this.pressedLayerPermille, required this.liveMinMs, required this.ambientMinMs, required this.dither});
  final int pressedLayerPermille;
  final int liveMinMs;
  final int ambientMinMs;
  final String dither;
}

/// The file's name for each class (what a board declares).
const Map<String, VrxDisplayClass> vrxClassNames = {
  'lcd_colour': VrxDisplayClass.lcdColour,
  'lcd_grey': VrxDisplayClass.lcdGrey,
  'epaper_grey': VrxDisplayClass.epaperGrey,
  'epaper_mono': VrxDisplayClass.epaperMono,
};

const Map<VrxDisplayClass, VrxClassRow> vrxClasses = {
  VrxDisplayClass.lcdColour: VrxClassRow(pressedLayerPermille: 200, liveMinMs: 0, ambientMinMs: 0, dither: 'none'),
  VrxDisplayClass.lcdGrey: VrxClassRow(pressedLayerPermille: 200, liveMinMs: 0, ambientMinMs: 0, dither: 'by_quality'),
  VrxDisplayClass.epaperGrey: VrxClassRow(pressedLayerPermille: 0, liveMinMs: 1000, ambientMinMs: 60000, dither: 'by_quality'),
