};

/// A pair of slots read together, and its WCAG contrast floor times 100.
class VrxPairFloor {
  const VrxPairFloor(this.bg, this.fg, this.minX100);
  final VrxSlot bg;
  final VrxSlot fg;
  final int minX100;
}

